(window.webpackJsonp=window.webpackJsonp||[]).push([[103],{540:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("1、主耶稣对门徒的第一个挑战：你是承认自己贫穷，得到那个现在还只能凭着盼望来远眺的神的国？还是愿意自己富足，现在就从富足当中立即获得安慰？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("2、他在这里挑战的，是你是否承认自己一无所有、极度缺乏，一无所能、极度无助，然后谦卑在耶稣面前，完全依赖他？如果答案是否定的，即使你穷得只剩一根打狗棍，你仍然是富足的，你仍然有祸了，你仍然与神的国无分，因为这根打狗棍就可以给你安慰。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("3、主耶稣对门徒的第二个挑战：你是愿意持续生活在一无所有、一无所能的状态中，以得到那将来完全的满足？还是你愿意现在就获得暂时的满足，而将来承受永恒的饥饿和哀恸？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("4、你需要持续地生活在承认自己一无所有、一无所能，完全依赖主耶稣的心态当中。如果你脱离了这种心态，你就会开始从财富、名望、权力、学位、工作成果等等物质资源中或者对自我的高举中，获得满足、获得喜乐。但由此而来的满足和喜乐，却是暂时。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("5、谦卑、感恩、进取。这就是有福之人的生命状态。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("6、这非常的神奇。一个认为自己极度缺乏、一无所有的人，却不会去追求获得自己所缺乏的以使自己得满足、得安慰，而是会去追求成为圣洁。而那些认为自己“富足”的人，因为他们从自己的富足中得到了安慰，却反而会去进一步去追求富足——也就是追求这些物质上的东西或者对自我的高举，以使自己不断获得安慰。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("7、主耶稣对门徒的第三个挑战：你是愿意要天上的赏赐、讨神的喜悦，还是受地上的欢迎、讨人的喜悦？前者你现在是看不见的、也是难以立即感知的。而后者是当下的、实实在在的、就摆在你眼前、会立即对你的身体和心理产生影响的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("8、中国的基督教是从西方传来的，而很多人在接受基督教的时候，也把随着基督教而来的、但又并不是基督教的一些东西一并接受了过来，当真理膜拜。有些自以为是为主受逼迫的人，其实是为了某种所谓普世价值观、为了某种政治经济体制、甚至是为了犹太复国主义而受逼迫。如果你因为这些东西而被逼迫，对不起，这不是为人子，因此没有任何天上的赏赐。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家平安。今天我们继续讲路加福音6:17~26节。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一、要现在的还是将来的？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在路加福音6：12节说，耶稣上到山上去祷告；之后13节说，他叫他的门徒来。那很自然，门徒们也是上到了山上。在山上，他从门徒中设立了十二个使徒。设立完了之后，第17节说到耶稣和他的门徒们下了山，到了一块平地上面。")])],1),t._v(" "),v("p",[t._v("此时除了门徒"),v("font",{attrs:{size:"5"}},[t._v("之外，也有很多百姓来到耶稣这里。路加说这些百姓来自于犹太全地、耶路撒冷、还有推罗、西顿的海边。我们知道耶稣主要的事工是在加利利地区。从地理上讲，加利利再往南，是撒玛利亚，撒玛利亚再往南，才是犹大地区。而耶路撒冷在地理上属于犹大地区，但因为其地位特殊，所以被单独拿出来说。加利利往北，就进入了完全外邦人的地区，叫做腓尼基。而推罗和西顿就是腓尼基的两座靠近地中海的城市。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从第17节我们可以看到，耶稣此时已经声名远播了。不仅加利利人知道他，远在南边的犹大地都知道他，甚至外邦人也知道他。经过犹太人公会的调查，虽然犹太的宗教领袖们认定他是异端，但群众们却不这么看，反而因为他们听说了耶稣之前的教导、之前行的神迹，更加愿意来跟随他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为什么这些人愿意来到耶稣这里呢？路加接着说，他们要听他讲道、指望自己的病得到医治，还有被污鬼缠磨的，需要得到解决。换句话说，他们有对耶稣的需要，这需要包括灵性上的，也包括身体上的。他们依赖耶稣来供应他们。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这些人承认自己有需要、把满足自己需要的希望寄托在耶稣身上、跋山涉水来到耶稣那里，祈求他、指望他、触摸他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当他们这样做的时候，其实就是表明了他们在耶稣面前的一种心态：我自己是不行的，我需要你。我无知，因此我需要你的教导；我身体有病，因此我需要你的医治；我被鬼缠磨，因此我需要你的能力。这是一种谦卑在耶稣面前、依靠他的心态。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而耶稣也满足了他们的需要，18节~19节讲到耶稣满足他们身体上的需要。18节说耶稣医治了那些被污鬼缠磨的，19节说到他们想摸耶稣的时候，他并没有拒绝，而是从身上发出能力来，医治了他们的疾病。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("接下来从第20节开始，路加记载了耶稣满足他们灵性上的需要，对他们讲道。这里提到耶稣在说话时，是举目看着门徒，这表明他接下来的讲道，不仅是他向百姓讲，也是他特别对门徒的教导。这篇讲道是主耶稣在平地上做的，区别于马太福音第5章的那篇赫赫有名的“登山宝训”，我们可以将他这篇讲道称作“平地宝训”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这篇讲道的第一个信息，就是关于需要与依赖的。他首先说了三种有福的情况，贫穷的人有福了、饥饿的人有福了、哀哭的人有福了。这三种人有什么共同点呢？就是客观上有需要，并且主观上承认自己有需要。正像当时在耶稣周围，那些在灵性和身体上都有需要的百姓们。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以在20~21节，他列举的贫穷、饥饿、哀哭的人，实际上是借着17~19节那些百姓们所做的一个引申，指出那些有福的人，就是那些承认自己有缺乏、有需要，并且谦卑在我面前、依靠我的人。他对门徒说，如果你们是这样的人，那么你们有福了。并且不仅仅是像刚才这些百姓们所经历过的那样，身体的疾病得到医治、身上的污鬼得以清理，而是将会得到一切。你缺乏的一切，都将会被满足；你不会再因缺乏而哀哭，必将会因满足而喜笑。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为什么呢？第20节说，如果你们是这样的人，那么“神的国是你们的”。神的国，不光是指神掌权的国度。如果是这样，那么现在任何人都处在“神的国”当中，因为神是创造主，他在一切事上掌权。耶稣说的神的国，不仅是指神掌权，而且是一个没有罪、没有痛苦、没有争战，包括人在内的一切受造之物都按照神的创造和谐相处、有序运行的地方。无论是人的灵性所需，还是身体的所需，在那里不会出现缺乏的状态，因此没有哀哭，也没有饥饿。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我要特别告诉大家的是，耶稣在第20节这里，用的是现在时态。也就是说，他告诉那些听道的人，如果你们承认自己有缺乏、有需要，并且谦卑在我面前、完全依赖我来满足你们的缺乏、需要，那么神的国，现在、客观上就与你们有份，你们就实际拥有了。或者我们也可以说，你现在就被接纳进神的国度当中了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("相反，如果你们不是这样的，你认为自己没有缺乏，你是富足的，因此不需要谦卑在我面前，不需要依赖我，在第24节，耶稣说，你们就有祸了。这里“有祸”的意思，结合第20节，当然就是指与神的国无分。他们之所以与神的国无分，耶稣说是因为他们“受过他们的安慰”。大家注意，和第20节一样，在第24节，耶稣这里同样用了现在时态。也就是那些自认为没有缺乏、富足的人，他们正从他们所拥有的东西，得到了安慰。这种安慰是什么呢？就是这些东西本身而带来的满足。而这就将导致他们与神的国无分了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，并列地看第20节、24节这两节经文，我们就可以看到：无论一个人是认为自己有缺乏，然后谦卑在耶稣面前、依靠耶稣来供应自己所需，还是一个人认为自己富足、没有缺乏、不需要依靠耶稣，其实在现在都得到了些什么。前一种人，得到的是神的国，而后一种人，得到的是自己当下自己所有的这些东西而带来的满足感。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我可以说，让人们选的话，大部分人会选后者。因为这当下的满足感，对于现在来说，是实实在在的；而神的国，你现在是看不见的。耶稣说你承认自己缺乏、来依靠我，现在就有神的国。那人们就会问，在哪儿？你说的那个没有缺乏的地方在哪儿？看不到。这是因为神的国还没有完全到来，第一种人现在有的，只是一个期权，或者最多可以说，你只能预先初尝到神国的滋味，并且坦白来说，这种预先初尝也更多是在心灵层面，这也是从外面看不见的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而后者所享有的现在、当下的满足，是实在的。那可不是期权，而是现金。我有一个很好的学位，或者有一篇很牛的论文，从这个学位、论文上面，我就有了以后找到一个好工作的安全感；我有房子，从这个房子上面，我就有了在一个城市安身立命的踏实感；我银行有很多存款，从这些存款上面，我就有了驾驭我未来人生的松弛感；我有名望，从这名望上面，我就有了在这世上立足的自豪感。这都是拥有这些现实的东西，可以带给我们的实实在在的满足感。所以拥有这些的人，会享受这些。而没有这些的人，会想尽办法来拥有它们，好使自己可以从这些东西本身上不断获得安慰。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以耶稣实际上在这里，向人们提出了他的第一个挑战。你是承认自己贫穷，得到那个现在还只能凭着盼望来远眺的神的国？还是愿意自己富足，现在就从富足当中立即获得安慰？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家注意，耶稣的这个挑战，和你是不是字面意义上的物质贫困或者家道富足没有关系。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当然我知道也有些人，会把这段经文与马太福音第5章登山宝训进行比较，认为路加在这里是删掉了两个字，这里的贫穷，是指“灵里贫穷”。什么叫灵里贫穷？就是自己和神的关系是糟糕的。这其实也有点牵强附会。耶稣在这里的教导和登山宝训的教导，个别语句在表面上有相同之处，但在整个上下文中，其实是在讲不同的事情。所以在路加福音这里，耶稣也不是讲论在你灵里贫穷还是灵里富足的问题。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他在这里挑战的，是你是否承认自己是贫穷的，不仅是灵里的，也包括物质上的。换句话说，你是否承认自己一无所有、极度缺乏，一无所能、极度无助，然后谦卑在耶稣面前，完全依赖他？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果答案是否定的，即使你在物质上穷得只剩一根打狗棍，你仍然是富足的，你仍然有祸了，你仍然与神的国无分，因为这根打狗棍就可以给你安慰；")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果答案是否定的，即使你自认为自己在灵性上是贫乏的（也就是你承认自己与神的关系是糟糕的）——但只要你仍然以为自己可以独立地做些什么可以与神和好，或者对“与神和好”这件事有所贡献，那么你仍然是富足的，你仍然有祸了，你仍然与神的国无分，因为你自己独立所做的这些事，其实就是你的自我，就可以给你带来安慰。我坦白说，这就是所有其他宗教的方法。他们认为自己可以通过行善、念经、祷告、或者举行一些仪式，全部或者部分地对“与神和好”这件事做出贡献。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么弟兄姐妹们，你们的选择是什么？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从外面看来，你们可能有很高的学位，有不错的研究成果，有住的地方，有衣服，有手机，有足够的食物，有车，有存款，有这个有那个。但你是否承认自己是贫穷的？也就是，你是否承认，自己其实在物质上是一无所有，极度匮乏的？你承不承认，刚才我所列举的这些东西，其实并不是你的。对你而言，你不拥有任何的东西，因此这些东西不会成为你的依靠，不会成为你的安慰。也因此，你要在世上活着，你只能谦卑地来到主耶稣面前，因为他是你继续活在这世上唯一的依靠、唯一的指望。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从灵里来看，你是否也承认自己是贫穷的？也就是，你是否承认，自己在神面前一无所能，你自己不能做任何事情，来讨神喜悦、与神和好。因此，你要在神面前活着，你只能把你的自我打压下去，谦卑地投靠在耶稣的荫蔽之下，因为他是你活在神面前唯一的依靠，唯一的指望。如果不是在他的荫蔽之下，那么你做的任何事情，才神看来都是肮脏的。而怎么进入到他的荫蔽之下？就是信靠他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，这些是很难的。我们人都喜欢从看得见的东西上得安慰、都喜欢从自我高举中得安慰。但在今天的经文中，主举目看着他的门徒们，对他们说，也是对我们在场的每个人说，你们千万不可如此，否则你们就与神的国无分了。主的门徒，必须把目光牢牢锁定在神的国，而不是其他东西上，因为那才是你们的产业。虽然当下不能立即看见，但事实上你们已经获得了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("二、要暂时的还是永恒的？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("接下来在第21节，耶稣用了两个将来时态，来表达饥饿和哀哭的人的福分。饥饿的人将会饱足，哀哭的人将会喜笑。在第20节提到贫穷的人会得到神的国，那么在第21节讲到的饱足、喜笑，很自然是因为神的国所带来的。同样，既然第20节，耶稣对他的门徒“承认自己贫穷”的挑战不仅是灵性上的，也是物质上的，因此第21节这里的饱足、喜笑，很自然也不仅仅是灵性上的饱足、喜笑，而是指神的国所带来的完全的、永远的满足，包括灵性、也包括物质上的。而大家也都知道，神的国的完全实现是在将来，所以，耶稣在第21节很自然地也使用了将来时态，来表达神的国到来时的场景。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家发现没有，按照第20节，耶稣的门徒们需要承认自己一无所有、一无所能，完全需要仰赖耶稣，这样他们在“现在”就能得到神的国。而按照第21节，神的国所带来的完全的、永远的饱足、喜笑又是“将来”的事。那么这就意味着，在现在和将来之间，他的门徒们需要持续地承认自己是处于“贫穷”、“饥饿”、“哀哭”的状态。换句话说，作为耶稣的门徒，你的心态，需要一直保持在承认自己一无所有，一无所能、谦卑在主面前、依赖主的这样一种状态当中。无论世界看来你拥有了多少财富、名望、权力，你都要承认这些不是你的，也不是你自己的能力获得的，在物质资源上，你一无所有、也一无所能；无论你与神的关系进深到何种程度，你都要承认这不是靠你自己达到的，在灵性的成长上，你自己是一无所有、也一无所能。你需要持续地生活在这个状态当中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你脱离了这种心态，你就会开始从财富、名望、权力、学位、工作成果等等物质资源中或者对自我的高举中，获得满足、获得喜乐，因为这些在现世中是即时、实在的。但是耶稣说，由此而来的满足和喜乐，却是暂时。在第25节，和第21节对应，耶稣也用了两个将来时态，来描述那些愿意享受这些暂时快感的人，在将来神的国完全实现时的状态：他们将会饥饿、哀痛哭泣。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以耶稣在这里又对他的门徒们提出了第二个挑战：你是愿意持续生活在一无所有、一无所能的状态中，以得到那将来完全的满足？还是你愿意现在就获得暂时的满足，而将来承受永恒的饥饿和哀恸？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，一时地承认自己极度缺乏、一无所有、无能为力，因此完全需要依赖主耶稣是容易的；但要一直保持在这个状态下，却是太难了。我们很容易就被世上的人所影响。他们去追求什么，我们也去追求什么；世上的人去追求世上的东西，因为他们需要从那些东西上得到安慰、得到饱足、得到喜笑。而基督徒也去追求，因为我们也认为这些东西可以带给我们安慰、饱足、喜笑。不仅追求，有些人还煞有介事地祷告，祈求主耶稣来帮我们追求。耶稣对他的门徒，也就是我们说，如果你们是这样，那么你们有祸了，当天国完全来临的时候，你们与其无份，会承受永恒的饥饿和哀恸。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("三、要地上的还是天上的？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("刚才我们已经讲了，有福之人是承认自己一无所有、一无所能，完全依赖于耶稣，并且一直处于这个状态当中。如果在这种状态中去生活，这个人会变成什么样呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("会非常谦卑，对不对？因为他知道自己什么都没有，什么都不行。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("会非常感恩，对不对？因为他知道自己有的、自己能做的，都是主耶稣所赐下的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("会非常进取，对不对？因为他一无所有，而主耶稣却赐给他丰丰富富的恩典，这恩典就会激励着他去做那主耶稣所喜悦的事，或者说，去做主耶稣所交付给他的事。这是什么事，还记得吗？我们上次讲的——去成为圣洁。他会非常进取地去追求成为圣洁。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("谦卑、感恩、进取。这就是有福之人的生命状态。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看，这非常的神奇。一个认为自己极度缺乏、一无所有的人，却不会去追求获得自己所缺乏的以使自己得满足、得安慰，而是会去追求成为圣洁，去追求敬虔。而那些认为自己“富足”的人（我刚才已经说了，这个富足包括了世俗物质上的，包括权利啊，财产啊，名声啊等等；也包括了灵性上，就是自我高举，认为自己可以独立解决与神的关系），因为他们从自己的富足中得到了安慰，却反而会去进一步去追求富足——也就是追求这些物质上的东西或者对自我的高举，以使自己不断获得安慰。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我刚才也已经说了，后者是这个世界上绝大多数人的状态。那么一个追求成为圣洁的人，在一群追求富足的人中，会遭遇什么呢？当然是冲突、逼迫。因为他所追求的，在其他人看来是恶的。就像其他人追求的，在他看来是恶的。所以这群人会弃掉他的名，就像他也会弃掉这群人的名一样。正如保罗在加拉太书第6:14节所说，就我而论，世界已经钉在十字架上；就世界而论，我已经钉在十字架上。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而主耶稣接着在第22节说，像这样被世界所恨恶、拒绝、辱骂的人，是有福的。因为他们在天上的赏赐是大的，就像古时候那些真先知一样。他们也是不随从世界的风俗，忠心履行神交付的使命，因此被世界所恨恶。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("同样相对照的，在第26节，主耶稣说，如果世上的人都说他们好，那么他们就有祸了，这意味着他们在天上没有赏赐——这里的意思不是说他们可以进入神的国，但得不到额外的赏赐，不是！而是说他们与神的国根本就无分。就像古时候那些假先知，世界上追求什么，他们也去追求什么；世上的人去追求世上的东西，以从那些东西上得到安慰、得到饱足、得到喜笑；假先知们也去追求，因为他们也要从这些东西中获得安慰、饱足、喜笑。他们有共同的追求，是同路人，世上的人当然说他们好。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以弟兄姐妹们，这里在此耶稣向我们提出了第三个挑战：你是愿意要天上的赏赐，还是愿意受地上的欢迎？或者换句话说，你是愿意讨神的喜悦，还是讨人的喜悦？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这看上去很容易选择，但实际上同样很难。因为天上的赏赐，你现在是看不见的；神的喜悦，你现在也是难以立即感知的。而世界的欢迎、人的喜悦，是当下的、实实在在的、就摆在你眼前、会立即对你的身体和心理产生影响的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("世上的人拒绝你、恨恶你、辱骂你、弃掉你的名，你是会痛苦、不好受的，这是真实、客观的。我不知道你们是否真实经历过这些。曾经参加我们聚会的一些在学校上学的弟兄姐妹因为信仰而被学校找谈话、甚至被恐吓，当时对他们的心理冲击是很大的。我还知道另一个在体制内工作的弟兄，因为服侍教会而丧失了晋升的机会。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("有人建议我不要向大家提起这些事，怕引起你们的恐慌和惧怕。但如果是这样，那我就更要提了。如果只是听我说，你都会恐慌和惧怕，那么当你实际面临的时候，就更会经受不住了。所以更要提前做好心理准备，主耶稣也早就告诉我们，我们在这个世上是有逼迫的，是会被人恨恶、拒绝、辱骂、恐吓、威胁的，当你处在这种境地中时，只有靠着强大的信心，真心相信此时那位宇宙的君王是在用赞赏的眼光看着你，为你在他的国度中留存了永恒的福乐，你才能像主耶稣在第23节这里说的“欢喜跳跃”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("另外，我也要特别提醒大家一点。注意第22节说的，是“为人子”的缘故。也就是说，你是因为主耶稣的缘故被人恨恶、拒绝、辱骂，才会有在天上的赏赐。如果不是为他的缘故，那么你受的这些是没有任何功效的，是活该。不仅没有功效，我甚至可以说，是可能会导致你与神的国无份的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在新冠期间，我曾经被拉入了一个基督徒的微信群。这个群里都是些搞法律的基督徒。这些人每天就在群里面骂政府的封控措施。其中有一个在重庆某个大学读法学博士的女生，有一天就组织了她的一批同学，在学校里拉横幅、集会，抗议政府的封控政策，说是限制人身自由，侵犯人权。结果这个人被学校进行了处分。她在群里说起这件事，其他人有的义愤填膺，为他打抱不平；也有的鼓励、安慰她，说她是为义受逼迫，在天上的赏赐是大的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家可能也知道，有些牧师，热衷于与政府对抗，出于各种原因，希望改变我们国家的政治体制，后来被关进监狱。在2019年香港暴乱的时候，也有很多牧师带着会众上街游行，反对政府，后来被处理。这些牧师自己以及他们教会的人，也认为这是在为义受逼迫。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们教会有个姐妹还给我讲了这么个事情。她说她在家里被孤立、鄙视。为什么呢？因为在这两年加沙的冲突中，她坚决站在以色列这一边；而她的家人认为以色列就是在进行种族灭绝，所以她和家人常常因此而争吵。她为什么支持以色列呢？因为她认为站在以色列一边就是站在上帝一边。所以在家中的这种状况，她自认为是为义受逼迫。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，我刚才举的这些例子，你怎么看？他们是在为义受逼迫吗？他们是“为人子”而被恨恶、拒绝、辱骂、被人弃掉他们的名吗？他们真的在天上有大的赏赐吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家一定要注意分辨。中国的基督教是从西方传来的，而很多人在接受基督教的时候，也把随着基督教而来的、但又并不是基督教的一些东西一并接受了过来，当做真理膜拜。刚才我说的这些例子中的这些人，其实不是为了人子，而是为了某种所谓普世价值观、为了某种政治经济体制、甚至是为了犹太复国主义而受逼迫。如果你因为这些东西而被逼迫，对不起，这不是为人子，没有任何赏赐。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我刚才说了，“为人子”而受逼迫，是指你去做主耶稣所喜悦的事，或者说，去做主耶稣所交付给你的事而受逼迫，也就是去追求成为圣洁而受逼迫。而追求成为圣洁，就是追求以荣耀神的目的、谦卑的心、去做神给你的具体的身份下所该做的事。这是我们上次讲的，记得吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当你去追求成为圣洁，这意味着什么？意味着你非常感恩，你为主耶稣所赐给你的而感恩；意味着你非常谦卑，你认可自己一无所有，完全仰赖主耶稣。谦卑、感恩、进取。刚才才讲过。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么当你不去追求成为圣洁，而是去追求自由、追求人权、追求中国政治体制改变、追求以色列占领巴勒斯坦，你这是在做什么？你这是要从这些事情上得安慰啊！就像那些追求财富、追求权力、追求名声、追求高举自我的人一样，好从财富、权利、名声、自我高举中得安慰一样。这是有祸的！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你明白这里面的陷阱了吗？有太多的基督徒、包括牧师，掉进去了，还不自知！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，在今天的经文中，主耶稣用两段鲜明的对比，向人们提出三个挑战。其实是三个选择：你是要选择那将来的神的国，在那里得到完全的满足；还是要选择现在的富足，立即获得安慰？你是要选择暂时的饱足、喜乐，还是要选择那永远的饱足和喜乐？你是要选择得天上的赏赐，还是要选择受地上的称赞？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你此时此刻可以在头脑中做出选择。但更重要的是，你要用你的生命状态来做出选择。如果你要的是那将来的神的国、永恒的饱足和喜乐、天上的赏赐，那么你就应该非常谦卑，承认自己一无所有，一无所能，需要完全依赖主耶稣；你就应该非常感恩，承认无论是你目前在世上存活的条件，还是你与神的和好，都是他所赐的；你就应该非常进取，被他的恩典所激励着，去追求成为圣洁，无论这个世界如何对待你。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当然，你也可以选择从财产、学位、研究成果、名望、权力、自我高举、自由、人权、某种政治制度、犹太复国主义或什么别的主义乱七八糟的东西中获得满足，或者去追求它们，好使它们来安慰你；你也可以去迎合这个世界，追求世界上的人追求的东西，让世界喜欢你。甚至你还可以向主耶稣来祷告，把他作为工具来追求这些东西。有很多基督徒就是这样的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我不知道你会做什么选择，我已经做了我的选择。如果你的选择和我不一样，请允许我借着诗篇第17篇分别为你和为我自己，做这样的祷告：“耶和华啊，求你用手救我脱离世人，脱离那只在今生有分的世人。求你把你的财宝充满他们的肚腹，使他们的儿女都可以饱尝，他们还有剩余留给他们的子孙。至于我，我必在义中见你的面；我醒了的时候，得见你的形象，就心满意足了。”")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);